(function(root){'use strict';
 const p=(name,color,text)=>({name,color,text}),common={1:p('Пресинаптическая мембрана','#9aaa8d','Условное окончание аксона; в открытом виде видны внутренние структуры.'),2:p('Постсинаптический шипик','#b4a68e','Мембрана головки шипика. Размеры и органеллы увеличены для обзора.'),3:p('Везикулярный пул','#d0b47a','Маркеры доступного пула; это не подсчёт настоящих везикул.'),4:p('Готовые везикулы','#c2a16b','Везикулы у активной зоны. Выделение задаётся выбранным протоколом.'),5:p('Митохондрия','#b78664','Морфологический ориентир; энергетический обмен отдельно не рассчитывается.'),6:p('Активная зона','#7c8d76','Пресинаптическая специализация выделения.'),7:p('Постсинаптическая плотность','#8f8477','Условное белковое уплотнение под мембраной.'),8:p('Пресинаптические Ca²⁺-каналы','#689b9c','Показаны как структура. В новых опытах детальная пресинаптическая кальциевая динамика не вычисляется.'),9:p('AMPA-рецепторы','#bba47a','Маркеры проводимости AMPA; видимое число не равно числу рецепторов в ткани.'),10:p('Пора слияния','#c39465','Условная геометрия события выделения.'),14:p('Актиновый каркас','#82999b','Условные нити шипика; перестройка цитоскелета не вычисляется.'),16:p('Маркеры глутамата','#c49a48','Иллюстрация количества/фазы, не отдельные посчитанные молекулы.'),17:p('Маркеры Ca²⁺','#629fae','Относительный кальциевый сигнал; не концентрация в молях.'),18:p('Ионный поток','#7f9eb2','Иллюстрация расчётного тока.'),19:p('Пора AMPA','#bba47a','Условное закрытие канала.'),20:p('Содержимое везикулы','#d0b47a','Условные маркеры содержимого.')};
 const parts={plasticity:{...common,21:p('NMDA: GluN2','#8f9cc1','Две условные GluN2-субъединицы обычного GluN1/GluN2-рецептора. Геометрия не атомная.'),22:p('NMDA: GluN1','#b9a0bf','Две условные GluN1-субъединицы. Глицин/D-серин считаются доступными; их концентрация не моделируется.'),23:p('Mg²⁺-блок поры','#738896','Маркер Mg²⁺ зависит от рассчитанного напряжение-зависимого блока. Это средний эффект, не траектория одного иона.'),24:p('Внутриклеточный рецепторный пул','#a5a6b4','Условный эндосомный компартмент. Трафик белков не рассчитан молекулярно.'),25:p('Внутриклеточные AMPA-маркеры','#c5b077','Иллюстративный рецепторный запас. Число мембранных маркеров отражает вес связи.')},astrocyte:{...common,30:p('Сома астроцита','#8ea99a','Авторская морфология, не реконструкция клетки. В разрезе видны ядро и условные ферментные маркеры.'),31:p('Сеть узлов и перемычек','#8ba897','Тонкие отростки образуют разветвляющуюся и замыкающуюся сеть. Форма вдохновлена исследованиями PAP, но не повторяет микроскопию.'),32:p('Перисинаптические отростки','#a8bda5','Связывают астроцитарную сеть с областью контакта. Охват в модели управляет эффективным захватом.'),33:p('Транспортёры EAAT','#71958e','Условные маркеры захвата глутамата. Реальная субъединичная структура и Na⁺-стехиометрия не воспроизведены.'),34:p('Глутаминсинтетаза','#9aa9bd','Маркеры превращения астроцитарного глутамата в глутамин; активность задаётся отдельно.'),35:p('Возврат глутамина','#b5b986','Схематический маршрут переноса к нейрону, не буквальная трубка между клетками.'),36:p('Узлы у синапса','#9cb49d','Увеличенные перисинаптические узлы и листовидные участки; охват не равен доле всех контактов мозга.'),37:p('Сосудистая ножка','#88a38c','Астроцитарный отросток рядом с капилляром. Гематоэнцефалический барьер в этом опыте не рассчитывается.'),38:p('Капилляр','#af8681','Контекстная структура с просветом, без расчёта кровотока.'),39:p('Ядро астроцита','#a599b0','Внутренняя структура, видимая в открытой соме.'),40:p('Глутамин','#b4bb78','Маркеры обмена глутамином. Траектории условны; количества берутся из баланса пулов.')},basal:{1:p('Кора: МРТ-контекст','#b5b4a4','Поверхность полушарий одного участника OpenNeuro. Не функциональная карта коры.'),2:p('Хвостатое ядро','#b4a1c3','Реконструировано из автоматической МРТ-сегментации aseg; форма упрощена.'),3:p('Скорлупа','#c3997e','МРТ-сегментация putamen; функциональные популяции D1/D2 не выделяются на этой МРТ.'),4:p('Бледный шар: общий сегмент','#b2b18b','В исходной aseg нет разделения GPe/GPi. Их отдельные точки являются схемой поверх общего сегмента.'),5:p('Таламус','#8faec1','МРТ-сегментация общего таламуса, без отдельных ядер.'),6:p('STN: схематический ориентир','#9daaad','Субталамическое ядро не сегментировано в используемом aseg. Положение условное, не МРТ-разметка.'),7:p('SNc: схематический ориентир','#9b8e7e','Дофаминергический источник обозначен условно; это не отдельная МРТ-сегментация чёрной субстанции.'),8:p('Стриатальные D1-популяции','#aa9870','Схематический маркер распределённой популяции, не отдельное ядро.'),9:p('Стриатальные D2-популяции','#8da5a1','Схематический маркер распределённой популяции. Оба пути могут быть активны одновременно.'),10:p('GPe: точка схемы','#b2b98e','Функциональный узел вынесен из общего сегмента pallidum для читаемости; не точная граница GPe.'),11:p('GPi: точка схемы','#b4a17f','Условная точка GPi, не отдельная МРТ-разметка. SNr и всё разнообразие выходных связей не показаны.'),12:p('Корковый вход: точка схемы','#b5b4a4','Схематическая точка входа, не локализация функции в данном участнике.')}};
 const edges=[['Кора → D1','exc'],['Кора → D2','exc'],['D1 → GPi','inh'],['D2 → GPe','inh'],['GPe → STN','inh'],['STN → GPi','exc'],['GPe → GPi','inh'],['GPi → таламус','inh'],['Таламус → кора','exc'],['Кора → STN: гиперпрямой','hyper'],['SNc → D1','dopamine'],['SNc → D2','dopamine']];edges.forEach(([name,type],i)=>parts.basal[50+i]=p(name,{exc:'#789f87',inh:'#bc8b91',hyper:'#78a7b8',dopamine:'#c3ab69'}[type],'Условный путь со стрелкой; не трактография. Движущиеся маркеры отражают активность модели, не измеренные импульсы.'));
 const refs={plasticity:[['Shouval, Bear & Cooper (2002) · Calcium-control model','https://pmc.ncbi.nlm.nih.gov/articles/PMC125058/'],['Destexhe et al. · Kinetic Models of Synaptic Transmission','https://papers.cnl.salk.edu/PDFs/Kinetic%20Models%20of%20Synaptic%20Transmission%201998-3229.pdf'],['Purves 2nd ed. (2001) · Molecular mechanisms of LTP','https://www.ncbi.nlm.nih.gov/books/NBK11101/']],astrocyte:[['Arizono et al. (2020) · Tripartite synapse nanoarchitecture','https://pubmed.ncbi.nlm.nih.gov/32312988/'],['Andersen (2025) · Glutamate/GABA–glutamine cycle','https://pmc.ncbi.nlm.nih.gov/articles/PMC11894596/'],['Schousboe et al. (2013) · Astrocytic neurotransmitter metabolism','https://pmc.ncbi.nlm.nih.gov/articles/PMC3744088/']],basal:[['OpenNeuro ds006128 · 1.0.11 · CC0','https://doi.org/10.18112/openneuro.ds006128.v1.0.11'],['Purves 2nd ed. (2001) · Basal ganglia circuits','https://www.ncbi.nlm.nih.gov/books/NBK10847/'],['Cui et al. (2013) · Concurrent activation of both pathways','https://pubmed.ncbi.nlm.nih.gov/23354054/']]};
 const modules=[{id:'plasticity',name:'PlasticityLab',title:'Синаптическая пластичность',subtitle:'Mg²⁺, NMDA, Ca²⁺ и сила связи',goal:'Меняйте напряжение, Mg²⁺ и протокол стимуляции; следите за Ca²⁺ и AMPA-маркерами. Скачайте сцену в GLB.',note:'Voltage-clamp и выбранное кальций-зависимое правило пластичности. Это не реконструкция эксперимента и не универсальная формула памяти.'},{id:'astrocyte',name:'AstrocyteLab',title:'Астроцит и трёхсторонний синапс',subtitle:'Захват глутамата и возврат глутамина',goal:'Рассмотрите сеть отростков, транспортёры и сосудистую ножку. Сравните быстрый захват и медленный обмен пулов.',note:'В модели сохраняются условные Glu/Gln-эквиваленты. Реальный цикл открыт: окисление, синтез de novo и полный азотный обмен не моделируются; скорости демонстрационные.'},{id:'basal',name:'BasalGangliaLab',title:'Цепи базальных ганглиев',subtitle:'МРТ-анатомия и условная схема связей',goal:'Сопоставьте ядра, прямой/непрямой/гиперпрямой пути и дофаминовую модуляцию. Отделяйте МРТ-формы от функциональных маркеров.',note:'МРТ одного участника: caudate, putamen, общий pallidum, thalamus. GPe/GPi, STN, SNc и пути — схематические наложения; модель популяционной активности не диагностирует заболевание.'}];
 const quiz={plasticity:[{prompt:'Что в этом опыте требуется для NMDA-зависимого кальциевого входа?',answers:['Глутамат, доступный соагонист и ослабление Mg²⁺-блока','Только наличие миелина','Полное отсутствие глутамата','Один цвет рецептора'],why:'В модели соагонист считается доступным, а связывание и напряжение-зависимый Mg²⁺-блок задают проводимость. Подробная молекулярная кинетика упрощена.'},{prompt:'Что означает изменение числа AMPA-маркеров?',answers:['Иллюстрацию относительного веса связи','Измеренное число рецепторов у пациента','Число клеток гиппокампа','Готовый диагноз расстройства памяти'],why:'Маркеры — условное отображение веса, полученного из выбранного правила пластичности; это не подсчёт молекул.'},{prompt:'Почему здесь указан voltage-clamp?',answers:['Мембранный потенциал задаётся экспериментальной командой','Потенциал сам вычисляется из полной морфологии','Каждый пик является клиническим приступом','Это другая запись частоты стимула'],why:'Потенциал удерживается на выбранном уровне. Потенциалы действия и полная электрическая модель шипика в этом опыте не рассчитываются.'}],astrocyte:[{prompt:'Какое преобразование показано внутри астроцитарного компартмента?',answers:['Глутамат → глутамин','Глутамат → миелин','Глутамин → молекула D2-рецептора','Мгновенный перенос всего белка в ядро'],why:'Глутаминсинтетаза участвует в превращении глутамата в глутамин; реальный метаболизм значительно шире показанной схемы.'},{prompt:'Что происходит при уменьшении захвата в этой модели?',answers:['Больше глутамата покидает область контакта','Исчезают все митохондрии мозга','Обязательно возникает клинический приступ','Количество вещества больше не сохраняется'],why:'Захват конкурирует с выходом из области контакта. Модель отслеживает и захваченные пулы, и вышедшее вещество; клинический исход из этого не выводится.'},{prompt:'Почему быстрый захват и обмен глутамина показаны раздельно?',answers:['Они относятся к разным временным масштабам','Астроцит не имеет отростков','Глутамин всегда превращается в глутамат за одну миллисекунду','Так определяется диагноз'],why:'Удаление медиатора из области контакта и метаболический возврат предшественника имеют разные скорости. Параметры здесь выбраны для учебного сравнения.'}],basal:[{prompt:'Какие структуры здесь действительно получены из aseg?',answers:['Хвостатое ядро, скорлупа, общий pallidum и таламус','Отдельные D1- и D2-нейроны','Все синапсы прямого пути','Каждая граница GPe и GPi'],why:'В используемом исходнике есть эти макроскопические сегменты. Функциональные популяции и разделение общего pallidum показаны условными точками.'},{prompt:'Можно ли трактовать прямой и непрямой пути как два взаимоисключающих выключателя?',answers:['Нет: обе популяции могут активироваться совместно','Да, по одному положению ползунка определяется движение пациента','Да, это следует из цвета стрелок','Да, непрямой путь всегда полностью молчит'],why:'Классическая схема полезна для понимания знаков связей, но исследования показывают совместную активность путей; реальная система сложнее этой rate-модели.'},{prompt:'Что обозначают линии между ядрами?',answers:['Условную схему связей со знаком и направлением','Измеренную трактографию данного участника','Непосредственный прогноз лечебной дозы','Отдельные видимые на МРТ аксоны'],why:'Линии построены по учебной схеме. Они не получены из диффузионной МРТ и не являются измеренными трактами.'}]};
 function install(D){for(const m of modules){m.sources=refs[m.id].map(([title,url],i)=>{const key='systems-'+m.id+'-'+i;D.sources[key]=[title,url];return key;});if(!D.modules.some(x=>x.id===m.id))D.modules.push(m);D.quiz[m.id]=quiz[m.id];}D.version=5;}
 root.SYSTEMS_CONTENT={parts,refs,modules,quiz,install};if(root.NEURO_CONTENT)install(root.NEURO_CONTENT);if(typeof module!=='undefined')module.exports=root.SYSTEMS_CONTENT;
})(globalThis);
